const fs = require('fs');
const csv = require('csv-parser');
const { groupByMonth, renderMonthly } = require('./monthly');

function parseLedger(filePath) {
  return new Promise((resolve, reject) => {
    const entries = [];
    fs.createReadStream(filePath)
      .pipe(csv())
      .on('data', (row) => {
        entries.push({
          date: row.date,
          amountCents: parseInt(row.amountCents, 10)
        });
      })
      .on('end', () => {
        resolve(entries);
      })
      .on('error', (error) => {
        reject(error);
      });
  });
}

async function handleBalanceCommand(filePath) {
  const entries = await parseLedger(filePath);
  // Existing balance logic
}

async function handleReportCommand(filePath) {
  const entries = await parseLedger(filePath);
  // Existing report logic
}

async function handleMonthlyCommand(filePath) {
  const entries = await parseLedger(filePath);
  const byMonth = groupByMonth(entries);
  console.log(renderMonthly(byMonth));
}

function usage() {
  console.log('Usage: ledger <command> <ledger.csv>');
  console.log('Commands: balance, report, monthly');
}

if (process.argv.length < 4) {
  usage();
} else {
  const command = process.argv[2];
  const filePath = process.argv[3];

  switch (command) {
    case 'balance':
      handleBalanceCommand(filePath);
      break;
    case 'report':
